import Foundation
import SwiftUI

// MARK: - Model

struct Article: Identifiable, Hashable, Codable, Sendable {
    let id: String
    let title: String
    let summary: String?
    let author: String?
    let publishedAt: Date?
    let imageURL: URL?

    enum CodingKeys: String, CodingKey {
        case id
        case title
        case summary
        case author
        case publishedAt = "published_at"
        case imageURL = "image_url"
    }
}

struct ArticlesPage: Codable, Sendable {
    let items: [Article]
    /// `nil` when there are no more pages.
    let nextPage: Int?

    enum CodingKeys: String, CodingKey {
        case items
        case nextPage = "next_page"
    }
}

// MARK: - Errors

enum ArticleServiceError: LocalizedError {
    case invalidURL
    case invalidResponse
    case httpStatus(Int)
    case decoding(Error)
    case transport(Error)

    var errorDescription: String? {
        switch self {
        case .invalidURL:
            return "The request URL is invalid."
        case .invalidResponse:
            return "The server returned an unexpected response."
        case .httpStatus(let code):
            return "The server responded with status \(code)."
        case .decoding:
            return "The response could not be read."
        case .transport(let error):
            return error.localizedDescription
        }
    }
}

// MARK: - Service

protocol ArticleServicing: Sendable {
    func fetchArticles(page: Int, pageSize: Int) async throws -> ArticlesPage
}

struct ArticleService: ArticleServicing {
    private let baseURL: URL
    private let session: URLSession

    init(baseURL: URL, session: URLSession = .shared) {
        self.baseURL = baseURL
        self.session = session
    }

    func fetchArticles(page: Int, pageSize: Int) async throws -> ArticlesPage {
        var components = URLComponents(
            url: baseURL.appendingPathComponent("articles"),
            resolvingAgainstBaseURL: false
        )
        components?.queryItems = [
            URLQueryItem(name: "page", value: String(page)),
            URLQueryItem(name: "per_page", value: String(pageSize))
        ]
        guard let url = components?.url else {
            throw ArticleServiceError.invalidURL
        }

        var request = URLRequest(url: url, timeoutInterval: 30)
        request.setValue("application/json", forHTTPHeaderField: "Accept")

        let (data, response) = try await perform(request)

        guard let http = response as? HTTPURLResponse else {
            throw ArticleServiceError.invalidResponse
        }
        guard (200..<300).contains(http.statusCode) else {
            throw ArticleServiceError.httpStatus(http.statusCode)
        }

        do {
            return try makeDecoder().decode(ArticlesPage.self, from: data)
        } catch {
            throw ArticleServiceError.decoding(error)
        }
    }

    private func perform(_ request: URLRequest) async throws -> (Data, URLResponse) {
        do {
            return try await session.data(for: request)
        } catch let error as URLError where error.code == .cancelled {
            throw CancellationError()
        } catch {
            throw ArticleServiceError.transport(error)
        }
    }

    private func makeDecoder() -> JSONDecoder {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .custom { decoder in
            let container = try decoder.singleValueContainer()
            let string = try container.decode(String.self)

            let fractional = ISO8601DateFormatter()
            fractional.formatOptions = [.withInternetDateTime, .withFractionalSeconds]
            if let date = fractional.date(from: string) {
                return date
            }

            let plain = ISO8601DateFormatter()
            plain.formatOptions = [.withInternetDateTime]
            if let date = plain.date(from: string) {
                return date
            }

            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Invalid ISO 8601 date: \(string)"
            )
        }
        return decoder
    }
}

// MARK: - View Model

@MainActor
final class ArticleListViewModel: ObservableObject {
    enum Phase: Equatable {
        case idle
        case loading
        case loaded
        case failed(String)
    }

    @Published private(set) var phase: Phase = .idle
    @Published private(set) var articles: [Article] = []
    @Published private(set) var isLoadingMore = false
    @Published private(set) var loadMoreError: String?
    @Published private(set) var refreshError: String?

    private let service: ArticleServicing
    private let pageSize: Int
    private let prefetchThreshold: Int

    private var nextPage: Int? = 1
    private var seenIDs: Set<String> = []
    /// Incremented on every refresh so stale responses from superseded requests are discarded.
    private var generation = 0

    init(service: ArticleServicing, pageSize: Int = 20, prefetchThreshold: Int = 5) {
        self.service = service
        self.pageSize = pageSize
        self.prefetchThreshold = prefetchThreshold
    }

    var hasMorePages: Bool { nextPage != nil }

    /// Performs the initial load exactly once.
    func loadIfNeeded() async {
        guard phase == .idle else { return }
        await refresh()
    }

    /// Reloads the first page, replacing current content on success.
    func refresh() async {
        generation &+= 1
        let current = generation

        phase = .loading
        isLoadingMore = false
        loadMoreError = nil

        let result = await fetch(page: 1)
        guard current == generation else { return }

        switch result {
        case .success(let page):
            seenIDs = []
            articles = []
            append(page.items)
            nextPage = page.nextPage
            refreshError = nil
            phase = .loaded

        case .failure(let error) where error is CancellationError:
            phase = articles.isEmpty ? .idle : .loaded

        case .failure(let error):
            let message = Self.message(for: error)
            if articles.isEmpty {
                phase = .failed(message)
            } else {
                refreshError = message
                phase = .loaded
            }
        }
    }

    /// Loads the next page if the given item is near the end of the list.
    func loadNextPageIfNeeded(currentItem item: Article) async {
        guard loadMoreError == nil,
              let index = articles.firstIndex(where: { $0.id == item.id }),
              index >= articles.count - prefetchThreshold else {
            return
        }
        await loadNextPage()
    }

    /// Loads the next page unconditionally (subject to guards against duplicate requests).
    func loadNextPage() async {
        guard let page = nextPage, !isLoadingMore, phase == .loaded else { return }

        let current = generation
        isLoadingMore = true
        loadMoreError = nil

        let result = await fetch(page: page)
        guard current == generation else { return }

        isLoadingMore = false

        switch result {
        case .success(let response):
            append(response.items)
            nextPage = response.nextPage

        case .failure(let error) where error is CancellationError:
            return

        case .failure(let error):
            loadMoreError = Self.message(for: error)
        }
    }

    /// Retries whichever operation failed most recently.
    func retry() async {
        if articles.isEmpty {
            await refresh()
        } else {
            await loadNextPage()
        }
    }

    // MARK: Private

    private func fetch(page: Int) async -> Result<ArticlesPage, Error> {
        do {
            return .success(try await service.fetchArticles(page: page, pageSize: pageSize))
        } catch {
            return .failure(error)
        }
    }

    /// Appends items while skipping any IDs already present, guarding against
    /// duplicates caused by items shifting between pages.
    private func append(_ newItems: [Article]) {
        let unique = newItems.filter { seenIDs.insert($0.id).inserted }
        articles.append(contentsOf: unique)
    }

    private static func message(for error: Error) -> String {
        (error as? LocalizedError)?.errorDescription ?? error.localizedDescription
    }
}

// MARK: - Views

struct ArticleListView: View {
    @StateObject private var viewModel: ArticleListViewModel
    private let onSelect: (Article) -> Void

    init(service: ArticleServicing, onSelect: @escaping (Article) -> Void = { _ in }) {
        _viewModel = StateObject(wrappedValue: ArticleListViewModel(service: service))
        self.onSelect = onSelect
    }

    var body: some View {
        NavigationStack {
            content
                .navigationTitle("Articles")
                .task { await viewModel.loadIfNeeded() }
                .refreshable { await viewModel.refresh() }
        }
    }

    @ViewBuilder
    private var content: some View {
        if viewModel.articles.isEmpty {
            emptyState
        } else {
            articleList
        }
    }

    @ViewBuilder
    private var emptyState: some View {
        switch viewModel.phase {
        case .idle, .loading:
            ProgressView()

        case .loaded:
            ContentUnavailableView(
                "No Articles",
                systemImage: "newspaper",
                description: Text("There is nothing to show right now.")
            )

        case .failed(let message):
            ContentUnavailableView {
                Label("Couldn't Load Articles", systemImage: "exclamationmark.triangle")
            } description: {
                Text(message)
            } actions: {
                Button("Try Again") {
                    Task { await viewModel.retry() }
                }
                .buttonStyle(.borderedProminent)
            }
        }
    }

    private var articleList: some View {
        List {
            if let refreshError = viewModel.refreshError {
                Section {
                    Label(refreshError, systemImage: "exclamationmark.circle")
                        .foregroundStyle(.red)
                }
            }

            Section {
                ForEach(viewModel.articles) { article in
                    Button {
                        onSelect(article)
                    } label: {
                        ArticleRow(article: article)
                    }
                    .buttonStyle(.plain)
                    .task {
                        await viewModel.loadNextPageIfNeeded(currentItem: article)
                    }
                }
            }

            paginationFooter
        }
        .listStyle(.plain)
    }

    @ViewBuilder
    private var paginationFooter: some View {
        if viewModel.isLoadingMore {
            HStack {
                Spacer()
                ProgressView()
                Spacer()
            }
            .listRowSeparator(.hidden)
        } else if let error = viewModel.loadMoreError {
            VStack(spacing: 8) {
                Text(error)
                    .font(.footnote)
                    .foregroundStyle(.secondary)
                    .multilineTextAlignment(.center)
                Button("Retry") {
                    Task { await viewModel.loadNextPage() }
                }
            }
            .frame(maxWidth: .infinity)
            .listRowSeparator(.hidden)
        }
    }
}

struct ArticleRow: View {
    let article: Article

    var body: some View {
        VStack(alignment: .leading, spacing: 6) {
            Text(article.title)
                .font(.headline)
                .lineLimit(2)

            if let summary = article.summary, !summary.isEmpty {
                Text(summary)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
                    .lineLimit(3)
            }

            HStack(spacing: 4) {
                if let author = article.author {
                    Text(author)
                }
                if let date = article.publishedAt {
                    Text(date, style: .date)
                }
            }
            .font(.caption)
            .foregroundStyle(.secondary)
        }
        .padding(.vertical, 4)
        .frame(maxWidth: .infinity, alignment: .leading)
        .contentShape(Rectangle())
        .accessibilityElement(children: .combine)
    }
}

